def compute(vars):
    operating_lease_obligations = vars["v1"]
    total_contractual_obligations = vars["v2"]

    if total_contractual_obligations == 0:
        return None

    ratio = operating_lease_obligations / total_contractual_obligations
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "operating_lease_obligations": operating_lease_obligations,
            "total_contractual_obligations": total_contractual_obligations,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
